package kr.tong.sky;
import android.graphics.Color;import android.text.*;import android.text.style.ForegroundColorSpan;import org.json.*;

/** Public seat markers are joined to operating flights; operators and cabins are never inferred. */
final class SeatMarks {
 static final String[] FIELDS={"prestigeAward","prestigeUpgrade","firstCombined"};
 static final String[] LABELS={"프레스티지 보너스","프레스티지 승급","퍼스트 보너스/승급 합산 · 구분 불가"};
 static final String[] FILTERS={"프레스티지·퍼스트 전체","프레스티지 보너스","프레스티지 승급","퍼스트 · 보너스/승급 합산"};
 static final int[] COLORS={0xff1265b5,0xffd06800,0xffad8c41};
 static final String[] DETAIL_LABELS={"일반석 보너스","프리미엄석 보너스","프레스티지 보너스","프리미엄석 승급","프레스티지 승급","퍼스트 보너스/승급 합산"};
 private static final String OPERATION_SOURCE="KE_WEEKLY_SCHEDULE_ALL_OPERATORS";
 static int filter(JSONObject search){int f=search.optInt("seatView",0);return f>=0&&f<FILTERS.length?f:0;}
 static boolean selected(int filter,int index){return filter==0||filter==index+1;}
 static boolean comparisonReady(JSONObject day){return day!=null&&day.optInt("operationSchema")==2&&OPERATION_SOURCE.equals(day.optString("operationSource"))&&day.optBoolean("operationCompleteOperators")&&day.optJSONArray("flights")!=null;}
 static boolean eligibleFlight(JSONObject row){return row!=null&&!row.optBoolean("weekdayExcluded")&&!row.optBoolean("timetableConflict")&&OperationSchedule.flightVerified(row)&&("CAPTURED".equals(row.optString("awardDataStatus"))||"NO_MARKS".equals(row.optString("awardDataStatus")));}
 static JSONObject savedFlags(JSONObject day){JSONObject saved=day==null?null:day.optJSONObject("savedAggregate");if(day==null||RepeatMarkerPolicy.excluded(day)||!"UNKNOWN".equals(day.optString("status"))||day.optBoolean("timetableReferenceConflict")||saved==null||!"OBSERVED".equals(saved.optString("status"))||!"SAVED_CALENDAR_AGGREGATE".equals(saved.optString("sourceKind")))return null;for(String field:Search.ALL_FIELDS)if(!(saved.opt(field) instanceof Boolean))return null;return saved;}
 static JSONObject calendarFlags(JSONObject day){JSONObject source=day==null?null:day.optJSONObject("savedCalendarSource");if(source==null||!"SAVED_CALENDAR".equals(source.optString("sourceKind"))||!"OBSERVED".equals(source.optString("status")))return null;for(String field:Search.ALL_FIELDS)if(!(source.opt(field) instanceof Boolean))return null;return source;}
 static JSONObject reviewFlags(JSONObject day){JSONObject stored=day==null?null:day.optJSONObject("repeatMarkerReviewFlags");if(!RepeatMarkerPolicy.review(day)||RepeatMarkerPolicy.excluded(day)||"NO_FLIGHT".equals(day.optString("status"))||stored==null||!"OBSERVED".equals(stored.optString("status"))||!"REVIEW_STORED_CALENDAR".equals(stored.optString("sourceKind")))return null;for(String field:Search.ALL_FIELDS)if(!(stored.opt(field) instanceof Boolean))return null;return stored;}
 static boolean eligibleDayFlight(JSONObject day,JSONObject row){return !RepeatMarkerPolicy.excluded(day)&&eligibleFlight(row);}
 static boolean verified(JSONObject day,boolean oz){if(day==null||"NO_FLIGHT".equals(day.optString("status"))||!oz&&RepeatMarkerPolicy.excluded(day))return false;if(oz)return "OBSERVED".equals(day.optString("status"));if(calendarFlags(day)!=null||reviewFlags(day)!=null||savedFlags(day)!=null)return true;if(!RepeatMarkerPolicy.excluded(day)&&(!"OBSERVED".equals(day.optString("status"))||!comparisonReady(day)))return false;JSONArray rows=day.optJSONArray("flights");if(rows!=null)for(int i=0;i<rows.length();i++)if(eligibleDayFlight(day,rows.optJSONObject(i)))return true;return false;}
 static boolean marked(JSONObject day,String field,boolean oz){if(!verified(day,oz))return false;if(oz)return day.optBoolean(field);JSONObject calendar=calendarFlags(day);if(calendar!=null)return calendar.optBoolean(field);JSONObject review=reviewFlags(day);if(review!=null&&review.optBoolean(field))return true;JSONObject saved=savedFlags(day);if(saved!=null)return saved.optBoolean(field);JSONArray rows=day.optJSONArray("flights");if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(eligibleDayFlight(day,row)&&OperationSchedule.markedFlight(row,field))return true;}return false;}
 static boolean available(JSONObject day,int filter){return available(day,filter,false);}
 static boolean available(JSONObject day,int filter,boolean oz){for(int i=0;i<CarrierUi.labels(oz).length;i++)if(selected(filter,i)&&marked(day,FIELDS[i],oz))return true;return false;}
 static CharSequence text(int date,JSONObject day,int filter,boolean fresh){return text(date,day,filter,fresh,false);}
 static CharSequence text(int date,JSONObject day,int filter,boolean fresh,boolean oz){boolean observed=verified(day,oz);SpannableStringBuilder out=new SpannableStringBuilder(date+(fresh&&observed?"★":"")+"\n");if(!oz&&RepeatMarkerPolicy.review(day))out.append("확인필요\n");if(!observed){if(!oz)out.append(RepeatMarkerPolicy.excluded(day)?"비운항 추정":day!=null&&day.optBoolean("timetableReferenceConflict")?"일정 불일치":TimetableReference.calendarLabel(day));return out;}for(int i=0;i<CarrierUi.labels(oz).length;i++)if(selected(filter,i)&&marked(day,FIELDS[i],oz)){int start=out.length();out.append("●");out.setSpan(new ForegroundColorSpan(CarrierUi.colors(oz)[i]),start,out.length(),Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);}return out;}
 static String description(JSONObject day,int filter){return description(day,filter,false);}
 static String description(JSONObject day,int filter,boolean oz){
  if(day==null)return "미확인";
  if(oz){if("NO_FLIGHT".equals(day.optString("status")))return "운항편 없음";if(!verified(day,true))return "미확인";}
  else{if(RepeatMarkerPolicy.excluded(day)&&!verified(day,false))return "대한항공 비운항 추정 · 해당 월 같은 요일 전체 세 표식";if(RepeatMarkerPolicy.review(day)&&!verified(day,false))return "확인필요 · 같은 요일의 표식 또는 확인 상태가 다름 · 제외하지 않음";if(OperationSchedule.allOperatorsNoFlight(day))return "운항편 없음 · 편별 대조 완료";if(!comparisonReady(day)&&calendarFlags(day)==null&&savedFlags(day)==null&&reviewFlags(day)==null)return "좌석 미확인 · 운항·편별 대조 전"+(TimetableReference.calendarLabel(day).isEmpty()?"":" · 참고표 "+TimetableReference.calendarLabel(day));if(!verified(day,false))return day.optBoolean("timetableReferenceConflict")?"운항 일정 불일치 · 표식 제외":excludedDirect(day)?"직접운항 비운항 · 지정요일 기준":"미확인 · 운항·편별 대조 전";}
  StringBuilder text=new StringBuilder();for(int i=0;i<CarrierUi.labels(oz).length;i++)if(selected(filter,i)&&marked(day,FIELDS[i],oz)){if(text.length()>0)text.append(", ");text.append(CarrierUi.labels(oz)[i]).append(" 표시");}
  if(text.length()==0)text.append(oz?"선택 항목의 공개 표식 없음":"확인된 항공편의 선택 표식 없음");if(!oz){if(RepeatMarkerPolicy.review(day))text.insert(0,"확인필요 · ");if(RepeatMarkerPolicy.excluded(day))text.append(" · 비운항 추정 · 해당 월 같은 요일 전체 세 표식");if(calendarFlags(day)!=null)text.append(" · 저장 달력 표식");else if(reviewFlags(day)!=null)text.append(" · 저장 표식 · 실제 운항 미확인");else if(savedFlags(day)!=null)text.append(" · 저장 표식 · 항공편별 대조 전");String kinds=serviceDescription(day);if(!kinds.isEmpty())text.append(" · ").append(kinds);if(day.optBoolean("operationPartial"))text.append(" · 일부 편 미확인");if(day.optBoolean("timetableReferenceConflict"))text.append(" · 일부 편 운항 일정 불일치 · 표식 제외");}return text.toString();
 }
 private static boolean excludedDirect(JSONObject day){JSONArray rows=day.optJSONArray("flights");if(rows==null)return false;for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(row!=null&&row.optBoolean("weekdayExcluded")&&OperationSchedule.flightVerified(row))return true;}return false;}
 static String serviceDescription(JSONObject day){if(RepeatMarkerPolicy.excluded(day)||day!=null&&day.has("savedCalendarSource"))return "";boolean own=false,partner=false;JSONArray rows=day==null?null:day.optJSONArray("flights");if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(!eligibleDayFlight(day,row))continue;own|="DIRECT".equals(row.optString("serviceKind"));partner|="CODESHARE".equals(row.optString("serviceKind"));}return own&&partner?"직접운항·공동운항":own?"직접운항":partner?"공동운항":"";}
 private static String value(JSONObject row,String field,String fallback){String value=row.optString(field).trim();return value.isEmpty()?fallback:value;}
 static String flightDetails(JSONObject day){
  if(day!=null&&day.has("savedCalendarSource")){String text="저장된 월별 좌석 달력 표식입니다. 항공편별 운항 대조 조건은 적용하지 않습니다.\n";if(RepeatMarkerPolicy.excluded(day))return text+"해당 월 같은 요일 전체에 세 표식이 반복되어 이 날짜 표식을 제외했습니다.\n";JSONObject source=calendarFlags(day);if(source==null)return text+"원본 달력의 이 날짜는 미확인 또는 비운항입니다.\n";for(int i=0;i<Search.ALL_FIELDS.length;i++)if(source.optBoolean(Search.ALL_FIELDS[i]))text+=DETAIL_LABELS[i]+": 표시 있음\n";return text;}
  StringBuilder text=new StringBuilder();JSONArray rows=day==null?null:day.optJSONArray("flights");if(rows==null||rows.length()==0)return "운항·편별 대조 전입니다. 저장된 합산 표식만으로 항공편별 좌석 정보를 표시하지 않습니다.\n";
  for(int n=0;n<rows.length();n++){
   JSONObject row=rows.optJSONObject(n);if(row==null)continue;if(text.length()>0)text.append('\n');boolean proof=OperationSchedule.flightProofValid(row);String kind=proof?("DIRECT".equals(row.optString("serviceKind"))?"직접운항":"공동운항"):"운항사 대조 전";
   text.append(value(row,"operatorName","운항사 미확인")).append(" · ").append(value(row,"number","편명 미확인")).append('\n').append(kind).append(" · ").append(value(row,"departureTime","시각 미확인")).append(" → ").append(value(row,"arrivalTime","시각 미확인")).append('\n');
   if(proof&&"NO_FLIGHT".equals(row.optString("operationStatus"))){text.append("비운항 · 좌석 표식 집계 제외\n");continue;}
   if(!proof||!"OPERATING".equals(row.optString("operationStatus"))){text.append("운항·편별 대조 전 · 좌석 표식 집계 보류\n");continue;}
   if(row.optBoolean("timetableConflict")){text.append("운항 일정 불일치 · 표식 제외\n공식 주간표와 참고 운항표가 달라 좌석 표식을 보류합니다.\n");continue;}
   if(RepeatMarkerPolicy.excluded(day)&&"DIRECT".equals(row.optString("serviceKind"))){text.append("비운항 추정 · 같은 달 해당 요일 전체 세 표식 · 집계 제외\n");continue;}
   String award=row.optString("awardDataStatus");if("UNKNOWN".equals(award)||!"CAPTURED".equals(award)&&!"NO_MARKS".equals(award)){text.append("운항 확인 · 좌석 표식 미확인\n");continue;}
   text.append("운항 확인\n");boolean any=false;for(int i=0;i<Search.ALL_FIELDS.length;i++)if(OperationSchedule.markedFlight(row,Search.ALL_FIELDS[i])){any=true;text.append(DETAIL_LABELS[i]).append(": 표시 있음\n");}if(!any)text.append("확인된 공개 표식 없음\n");
  }
  if(text.length()==0)text.append("운항·편별 대조 전입니다.\n");if(day!=null&&day.optBoolean("operationPartial"))text.append("\n일부 항공편은 운항·좌석 대조가 끝나지 않았습니다.\n");return text.toString();
 }
 static CharSequence legend(){return legend(false);}
 static CharSequence legend(boolean oz){SpannableStringBuilder out=new SpannableStringBuilder();for(int i=0;i<CarrierUi.labels(oz).length;i++){int start=out.length();out.append("● ").append(CarrierUi.labels(oz)[i]).append('\n');out.setSpan(new ForegroundColorSpan(CarrierUi.colors(oz)[i]),start,out.length()-1,Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);}if(oz)return out.append("★ 새 표식 · 회색: 미조회/미확인·비운항\n아시아나 비즈니스 좌석 표식입니다.");return out.append("★ 새 표식 · 주황색 확인필요: 같은 요일의 결과가 다름 · 회색: 미조회·미확인·비운항\n유럽·미주(캐나다 포함)은 원본 달력의 월별 같은 요일 세 표식 반복 기준으로 판정합니다. 항공편과 일반석 등 전체 유형은 날짜 상세에서 확인할 수 있습니다.\n퍼스트는 원본에서 보너스·승급을 합쳐 제공하므로 개별 여부는 확인할 수 없습니다.");}
}
